<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Modal, message } from 'ant-design-vue'
import { canIam, iamMessage } from '@/services/iamAccess'
import { listDepartments } from '@/services/iamDepartments'
import { roleQuery, roleCommand, assertRolePreview, type RoleAssignment, type RolePreview, type RoleScope } from '@/services/iamRoles'
import type { DepartmentSummary } from '@/types/iam'
import OwnAccountVerification from '@/components/account/OwnAccountVerification.vue'
import { useAccountProof } from '@/composables/useAccountProof'
const props=defineProps<{subjectKind:'employee'|'department';subjectId:string}>(),emit=defineEmits<{back:[];saved:[]}>()
const loading=ref(true),busy=ref(false),error=ref(''),editing=ref(false),current=ref<RoleAssignment|null>(null),choice=ref(''),scopeRefs=ref<string[]>([]),departments=ref<DepartmentSummary[]>([]),companies=ref<Array<{id:string;name:string}>>([]),preview=ref<RolePreview|null>(null),original=ref('')
const proof=useAccountProof(()=>{preview.value=null}),canEdit=computed(()=>canIam('iam.roles.assign')&&canIam(props.subjectKind==='department'?'iam.departments.manage':'iam.access.manage'))
const dirty=computed(()=>editing.value&&JSON.stringify([choice.value,[...scopeRefs.value].sort()])!==original.value),own=computed(()=>props.subjectKind==='employee')
let generation=0
function reset(){choice.value=own.value?(current.value?.mode==='DIRECT'?current.value.role_key:current.value?.mode||'FOLLOW_DEPARTMENT'):current.value?.role_key||'';scopeRefs.value=current.value?.responsibilities?.map(row=>row.scope_ref)||[];original.value=JSON.stringify([choice.value,[...scopeRefs.value].sort()]);preview.value=null}
async function load(preserve=false){const run=++generation;loading.value=true;error.value='';try{const next=await roleQuery<RoleAssignment>(own.value?'get_assignment':'get_department_role',own.value?{employee_id:props.subjectId}:{department:props.subjectId});if(run!==generation)return;current.value=next;if(!preserve){reset();editing.value=false}preview.value=null;if(canEdit.value){const scope=await listDepartments('all');if(run!==generation)return;departments.value=scope.items.filter(row=>row.confirmed);companies.value=scope.companies}}catch(e){if(run===generation)error.value=iamMessage(e)}finally{if(run===generation)loading.value=false}}
function params(){if(!current.value)throw new Error('请先读取当前角色。');const mode=['staff','clerk','admin'].includes(choice.value)?'DIRECT':choice.value;const responsibilities:RoleScope[]=choice.value==='clerk'||choice.value==='admin'?scopeRefs.value.map(scope_ref=>({scope_type:choice.value==='clerk'?'DEPARTMENT':'COMPANY',scope_ref,include_descendants:0})):[];return own.value?{employee_id:props.subjectId,mode,role_key:mode==='DIRECT'?choice.value:'',responsibilities,expected_version:current.value.version}:{department:props.subjectId,role_key:choice.value,expected_version:current.value.version}}
async function prepare(){if(busy.value||!canEdit.value)return;busy.value=true;error.value='';try{preview.value=assertRolePreview(await roleCommand<RolePreview>(own.value?'preview_assignment':'preview_department_role',params()))}catch(e){error.value=iamMessage(e)}finally{busy.value=false}}
async function commit(){if(busy.value||!preview.value||!proof.valid.value)return;busy.value=true;error.value='';try{await roleCommand(own.value?'save_assignment':'save_department_role',{...params(),context_revision:preview.value.context_revision,request_id:crypto.randomUUID()});proof.invalidate();editing.value=false;await load();emit('saved');message.success('角色安排已保存，已有禁用和限制继续保留。')}catch(e){error.value=iamMessage(e);preview.value=null}finally{busy.value=false}}
async function requestLeave(){if(busy.value)return false;if(!dirty.value)return true;return new Promise<boolean>(resolve=>Modal.confirm({title:'放弃尚未保存的角色安排？',okText:'放弃草稿',cancelText:'继续编辑',onOk:()=>resolve(true),onCancel:()=>resolve(false)}))}
async function back(){if(await requestLeave())emit('back')}
watch(()=>[props.subjectKind,props.subjectId],()=>load(),{immediate:true});defineExpose({requestLeave})
</script>
<template><section class="role-settings"><div class="role-heading"><a-button :disabled="busy" @click="back">返回应用清单</a-button><h2>{{own?'员工考勤角色':'部门默认考勤角色'}}</h2></div><a-alert v-if="error" :message="error" type="warning" show-icon/><a-button v-if="error" :disabled="busy" @click="load(editing)">重新读取，保留草稿</a-button><a-skeleton v-if="loading" active/><template v-else-if="current"><section class="result"><h3>{{own?(current.effective_access?.allowed?'当前有可用功能':'当前暂不可用'):(current.role_key==='staff'?'部门默认：普通员工':'不默认开通角色')}}</h3><p v-if="own">{{current.effective_access?.reason || '实际功能以当前发布版本和已有访问限制为准。'}}</p><p v-if="own">角色来源：{{current.mode==='DIRECT'?'个人单独指定':current.mode==='NONE'?'未选角色':'跟随所属部门默认'}}<span v-if="current.selected_role?.published_revision"> · 当前发布 v{{current.selected_role.published_revision}}</span></p><RouterLink v-if="own&&current.department&&canIam('iam.departments.read')" :to="{path:'/hbos/admin/departments',query:{department:current.department,company:current.company,tab:'apps'}}">查看所属部门默认</RouterLink><p v-if="!own">个人单独指定的角色保持；未开户、禁用和已有 deny 的成员按实际状态核对。</p></section><a-button v-if="!editing&&canEdit" type="primary" @click="reset();editing=true">{{own?'设置角色与范围':'调整默认角色'}}</a-button><template v-if="editing"><OwnAccountVerification password-only @verified="proof.sync" @invalidated="proof.invalidate"/><a-form layout="vertical" @submit.prevent="prepare"><fieldset :disabled="busy||Boolean(preview)"><a-form-item :label="own?'考勤角色':'部门默认角色'"><a-select v-model:value="choice" @change="scopeRefs=[];preview=null"><a-select-option v-if="own" value="FOLLOW_DEPARTMENT">跟随部门默认</a-select-option><a-select-option value="staff">普通员工 · 仅本人</a-select-option><a-select-option v-if="own" value="clerk">部门考勤员</a-select-option><a-select-option v-if="own" value="admin">考勤管理员</a-select-option><a-select-option :value="own?'NONE':''">{{own?'不选角色':'不默认开通'}}</a-select-option></a-select></a-form-item><a-form-item v-if="choice==='clerk'" label="明确负责的部门（不默认含下级）"><a-select v-model:value="scopeRefs" mode="multiple" :options="departments.map(row=>({value:row.id,label:row.name+' · '+row.company}))"/></a-form-item><a-form-item v-if="choice==='admin'" label="明确负责的一个公司"><a-select :value="scopeRefs[0]" :options="companies.map(row=>({value:row.id,label:row.name}))" @change="(value:string)=>scopeRefs=[value]"/></a-form-item><p>选择角色不会自动开户、解除临时禁用或清除已有禁止。本人的查询始终只看本人。</p></fieldset><a-button :disabled="busy" @click="editing=false;reset()">取消修改</a-button><a-button type="primary" html-type="submit" :loading="busy" :disabled="!dirty||Boolean(preview)">核对实际结果</a-button></a-form><section v-if="preview" class="preview" aria-live="polite"><h3>保存后的实际结果</h3><template v-if="own"><p>{{preview.after?.allowed?'有可用功能':'当前暂不可用'}}：{{preview.after?.reason || '已核对发布版本、账号和旧限制。'}}</p><p v-for="row in preview.after?.operations" :key="JSON.stringify(row)">{{row.label || '已登记功能'}} · {{row.scope_type==='SELF'?'本人':row.scope_ref}}：{{row.allowed?'可用':'不可用'}}</p></template><template v-else><p>跟随默认 {{preview.reference_count}} 人；实际权限变化 {{preview.effective_changed_count}} 人；个人安排保留 {{preview.personal_preserved}} 人。</p><p v-for="row in preview.members" :key="row.employee">{{row.name}}：{{row.changed?'实际权限将变化':'实际权限保持'}} {{row.reason}}</p></template><a-button :disabled="busy" @click="preview=null">返回修改</a-button><a-button type="primary" :loading="busy" :disabled="!proof.valid.value||!preview.changed" @click="commit">确认保存</a-button></section></template></template></section></template>
<style scoped>.role-settings{display:grid;gap:16px;font-size:16px}.role-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.role-heading h2{margin:0;font-size:20px}.result,.preview{border:1px solid var(--hbos-border-subtle);padding:20px;border-radius:12px}.result h3{margin-top:0}.ant-btn+.ant-btn{margin-left:12px}fieldset{border:0;padding:0;margin:0;min-width:0}.ant-form{max-width:700px}.ant-select{width:100%}</style>
